//! Cross-language compatibility tests for ED25519 key/signature interop
//! between the Go agent and the Rust agent.
//!
//! These tests verify:
//! 1. Keys generated by Go (PKCS8 PEM) can be loaded in Rust
//! 2. Keys generated by Rust can be loaded by Go
//! 3. Signatures from Go can be verified in Rust
//! 4. The signing protocol (payload || timestamp) is identical

use ed25519_dalek::SigningKey;
use pkcs8::{DecodePrivateKey, EncodePrivateKey, LineEnding};
use spki::{DecodePublicKey, EncodePublicKey};
use std::process::Command;
use tempfile::TempDir;

/// Test that a Rust-generated PKCS8 PEM private key has the correct format
/// that Go's x509.ParsePKCS8PrivateKey can parse.
#[test]
fn test_rust_key_format_matches_go() {
    let mut csprng = rand::rngs::OsRng;
    let signing = SigningKey::generate(&mut csprng);

    // Export as PKCS8 PEM
    let pem = signing.to_pkcs8_pem(LineEnding::LF).unwrap();
    let pem_str: &str = pem.as_ref();

    // Verify PEM header/footer match Go output
    assert!(pem_str.starts_with("-----BEGIN PRIVATE KEY-----\n"));
    assert!(pem_str.trim_end().ends_with("-----END PRIVATE KEY-----"));

    // Verify round-trip through PKCS8
    let loaded = SigningKey::from_pkcs8_pem(pem_str).unwrap();
    assert_eq!(signing.to_bytes(), loaded.to_bytes());
}

/// Test that public key PEM format matches Go's x509.MarshalPKIXPublicKey output.
#[test]
fn test_rust_pubkey_format_matches_go() {
    let mut csprng = rand::rngs::OsRng;
    let signing = SigningKey::generate(&mut csprng);
    let verifying = signing.verifying_key();

    let pem = verifying.to_public_key_pem(LineEnding::LF).unwrap();

    // Verify PEM header/footer match Go output
    assert!(pem.starts_with("-----BEGIN PUBLIC KEY-----\n"));
    assert!(pem.trim_end().ends_with("-----END PUBLIC KEY-----"));

    // Round-trip
    let loaded = ed25519_dalek::VerifyingKey::from_public_key_pem(&pem).unwrap();
    assert_eq!(verifying.as_bytes(), loaded.as_bytes());
}

/// Test that the signing protocol (payload || timestamp) produces signatures
/// that can be verified using the standard algorithm.
#[test]
fn test_signing_protocol_payload_timestamp_concat() {
    use ed25519_dalek::{Signer, Verifier};

    let mut csprng = rand::rngs::OsRng;
    let signing = SigningKey::generate(&mut csprng);
    let verifying = signing.verifying_key();

    let payload = b"test-state-fingerprint";
    let timestamp = "1709683200"; // Unix seconds as decimal string

    // Build message the same way Go does: payload || timestamp
    let mut msg = Vec::new();
    msg.extend_from_slice(payload);
    msg.extend_from_slice(timestamp.as_bytes());

    let sig = signing.sign(&msg);
    assert!(verifying.verify(&msg, &sig).is_ok());

    // Verify that a different concatenation order would fail
    let mut wrong_msg = Vec::new();
    wrong_msg.extend_from_slice(timestamp.as_bytes());
    wrong_msg.extend_from_slice(payload);
    assert!(verifying.verify(&wrong_msg, &sig).is_err());
}

/// Test actual cross-language interop using a Go helper program.
/// This test is ignored by default since it requires the Go toolchain.
/// Run with: cargo test -- --ignored
#[test]
#[ignore = "requires Go toolchain"]
fn test_go_generated_key_loads_in_rust() {
    let dir = TempDir::new().unwrap();

    // Write a small Go program that generates a key and saves it
    let go_prog = r#"
package main

import (
    "crypto/ed25519"
    "crypto/rand"
    "crypto/x509"
    "encoding/pem"
    "fmt"
    "os"
    "path/filepath"
)

func main() {
    dir := os.Args[1]
    pub, priv, err := ed25519.GenerateKey(rand.Reader)
    if err != nil {
        fmt.Fprintf(os.Stderr, "generate: %v\n", err)
        os.Exit(1)
    }

    // Save private key as PKCS8 PEM
    der, _ := x509.MarshalPKCS8PrivateKey(priv)
    privPEM := pem.EncodeToMemory(&pem.Block{Type: "PRIVATE KEY", Bytes: der})
    os.WriteFile(filepath.Join(dir, "agent.key"), privPEM, 0600)

    // Save public key as PKIX PEM
    pubDER, _ := x509.MarshalPKIXPublicKey(pub)
    pubPEM := pem.EncodeToMemory(&pem.Block{Type: "PUBLIC KEY", Bytes: pubDER})
    os.WriteFile(filepath.Join(dir, "public.pem"), pubPEM, 0644)

    // Sign a test message: "hello" + "12345"
    msg := append([]byte("hello"), []byte("12345")...)
    sig := ed25519.Sign(priv, msg)
    os.WriteFile(filepath.Join(dir, "signature.bin"), sig, 0644)
}
"#;

    let go_file = dir.path().join("gen.go");
    std::fs::write(&go_file, go_prog).unwrap();

    let output = Command::new("go")
        .args(["run", go_file.to_str().unwrap(), dir.path().to_str().unwrap()])
        .output()
        .expect("go must be available for this test");

    if !output.status.success() {
        panic!(
            "Go program failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    // Load the Go-generated private key in Rust
    let priv_pem = std::fs::read_to_string(dir.path().join("agent.key")).unwrap();
    let signing = SigningKey::from_pkcs8_pem(&priv_pem).expect("Rust must parse Go PKCS8 PEM");

    // Load the Go-generated public key in Rust
    let pub_pem = std::fs::read_to_string(dir.path().join("public.pem")).unwrap();
    let verifying = ed25519_dalek::VerifyingKey::from_public_key_pem(&pub_pem)
        .expect("Rust must parse Go PKIX PEM");

    // Verify the keys match
    assert_eq!(signing.verifying_key().as_bytes(), verifying.as_bytes());

    // Verify the Go-generated signature in Rust
    let sig_bytes = std::fs::read(dir.path().join("signature.bin")).unwrap();
    let sig_array: [u8; 64] = sig_bytes.try_into().expect("signature must be 64 bytes");
    let sig = ed25519_dalek::Signature::from_bytes(&sig_array);

    let mut msg = Vec::new();
    msg.extend_from_slice(b"hello");
    msg.extend_from_slice(b"12345");

    use ed25519_dalek::Verifier;
    verifying
        .verify(&msg, &sig)
        .expect("Rust must verify Go-generated signature");
}

/// Test that Rust-generated key can be loaded by Go.
/// Ignored by default since it requires Go toolchain.
#[test]
#[ignore = "requires Go toolchain"]
fn test_rust_generated_key_loads_in_go() {
    let dir = TempDir::new().unwrap();

    // Generate key in Rust and save
    let mut csprng = rand::rngs::OsRng;
    let signing = SigningKey::generate(&mut csprng);
    let pem = signing.to_pkcs8_pem(LineEnding::LF).unwrap();
    let pem_str: &str = pem.as_ref();
    std::fs::write(dir.path().join("agent.key"), pem_str.as_bytes()).unwrap();

    // Sign a message in Rust
    use ed25519_dalek::Signer;
    let mut msg = Vec::new();
    msg.extend_from_slice(b"hello");
    msg.extend_from_slice(b"12345");
    let sig = signing.sign(&msg);
    std::fs::write(dir.path().join("signature.bin"), sig.to_bytes()).unwrap();

    // Save public key PEM
    let pub_pem = signing
        .verifying_key()
        .to_public_key_pem(LineEnding::LF)
        .unwrap();
    std::fs::write(dir.path().join("public.pem"), &pub_pem).unwrap();

    // Write a Go program that loads the key and verifies the signature
    let go_prog = r#"
package main

import (
    "crypto/ed25519"
    "crypto/x509"
    "encoding/pem"
    "fmt"
    "os"
    "path/filepath"
)

func main() {
    dir := os.Args[1]

    // Load private key
    privData, _ := os.ReadFile(filepath.Join(dir, "agent.key"))
    block, _ := pem.Decode(privData)
    if block == nil || block.Type != "PRIVATE KEY" {
        fmt.Fprintln(os.Stderr, "bad PEM")
        os.Exit(1)
    }
    parsed, err := x509.ParsePKCS8PrivateKey(block.Bytes)
    if err != nil {
        fmt.Fprintf(os.Stderr, "parse: %v\n", err)
        os.Exit(1)
    }
    priv, ok := parsed.(ed25519.PrivateKey)
    if !ok {
        fmt.Fprintf(os.Stderr, "type: %T\n", parsed)
        os.Exit(1)
    }

    // Load public key
    pubData, _ := os.ReadFile(filepath.Join(dir, "public.pem"))
    pubBlock, _ := pem.Decode(pubData)
    parsedPub, err := x509.ParsePKIXPublicKey(pubBlock.Bytes)
    if err != nil {
        fmt.Fprintf(os.Stderr, "parse pub: %v\n", err)
        os.Exit(1)
    }
    pub := parsedPub.(ed25519.PublicKey)

    // Verify keys match
    if !priv.Public().(ed25519.PublicKey).Equal(pub) {
        fmt.Fprintln(os.Stderr, "keys don't match")
        os.Exit(1)
    }

    // Verify Rust-generated signature
    sigData, _ := os.ReadFile(filepath.Join(dir, "signature.bin"))
    msg := append([]byte("hello"), []byte("12345")...)
    if !ed25519.Verify(pub, msg, sigData) {
        fmt.Fprintln(os.Stderr, "signature verification failed")
        os.Exit(1)
    }

    fmt.Println("OK")
}
"#;

    let go_file = dir.path().join("verify.go");
    std::fs::write(&go_file, go_prog).unwrap();

    let output = Command::new("go")
        .args([
            "run",
            go_file.to_str().unwrap(),
            dir.path().to_str().unwrap(),
        ])
        .output()
        .expect("go must be available for this test");

    if !output.status.success() {
        panic!(
            "Go verification failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    assert!(stdout.contains("OK"), "Go program should print OK");
}
